/**
 * AI assistant sidebar tab.
 *
 * Phase 1 scope:
 *   - settings panel (provider / baseUrl / apiKey / model)
 *   - chat panel with markdown rendering
 *   - upload protocol document, ask backend to extract a normalised
 *     {device, transport, codec, properties, methods} description, render it
 *
 * Communication with the backend goes through the admin API at /ai/*.
 * The api key never leaves the server side once stored.
 */
RED.sidebar.ai = (function () {

    var content;
    var toolbar;
    var chatList;
    var inputBox;
    var sendBtn;
    var attachBtn;
    var attachInput;
    var attachmentList;
    var selectionList;
    var settingsBtn;
    var skillsBtn;
    var settingsPanel;
    var skillsPanel;
    var skillsListEl;
    var chatPanel;

    var providerSelect;
    var modelInput;
    var baseUrlInput;
    var apiKeyInput;
    var saveBtn;

    var conversation = [];
    var sending = false;
    var configCache = null;
    var pendingAttachments = [];
    var MAX_ATTACHMENT_BYTES = 200000;
    var contextNodeIds = [];
    var dismissedNodeIds = {};
    var sessions = {};
    var GLOBAL_SESSION_ID = "__global__";
    var activeSessionId = GLOBAL_SESSION_ID;

    function getSession(id) {
        if (!sessions[id]) {
            sessions[id] = { conversation: [], renderedHtml: null };
        }
        return sessions[id];
    }

    function captureSessionState() {
        if (!activeSessionId) { return; }
        var s = getSession(activeSessionId);
        s.conversation = conversation;
        s.renderedHtml = chatList ? chatList.html() : null;
    }

    function activateSession(id) {
        captureSessionState();
        activeSessionId = id || GLOBAL_SESSION_ID;
        var s = getSession(activeSessionId);
        conversation = s.conversation || [];
        if (chatList) {
            chatList.empty();
            if (s.renderedHtml) {
                chatList.html(s.renderedHtml);
                chatList.scrollTop(chatList[0].scrollHeight);
            } else {
                renderWelcome();
            }
        }
        refreshSessionIndicator();
    }

    var sessionLabelSpan;

    function activeFlowSessionId() {
        if (RED.workspaces && typeof RED.workspaces.active === "function") {
            return RED.workspaces.active() || GLOBAL_SESSION_ID;
        }
        return GLOBAL_SESSION_ID;
    }

    function flowDisplayLabel(id) {
        if (!id || id === GLOBAL_SESSION_ID) {
            return RED._("sidebar.ai.globalSession", { defaultValue: "全局" });
        }
        var ws = RED.nodes.workspace ? RED.nodes.workspace(id) : null;
        if (ws && ws.label) { return ws.label; }
        var sf = RED.nodes.subflow ? RED.nodes.subflow(id) : null;
        if (sf && sf.name) { return sf.name; }
        return id.slice(0, 6);
    }

    function refreshSessionIndicator() {
        if (!sessionLabelSpan) { return; }
        sessionLabelSpan.text(flowDisplayLabel(activeSessionId));
    }

    function init() {
        content = document.createElement("div");
        content.className = "red-ui-sidebar-ai";

        toolbar = $("<div>", { class: "red-ui-sidebar-header red-ui-info-toolbar red-ui-sidebar-ai-toolbar" }).appendTo(content);

        var titleSpan = $('<span class="red-ui-sidebar-ai-title"></span>')
            .text(RED._("sidebar.ai.label", { defaultValue: "AI" }))
            .appendTo(toolbar);
        sessionLabelSpan = $('<span class="red-ui-sidebar-ai-session-indicator"></span>').appendTo(toolbar);

        var rightGroup = $('<span class="button-group" style="float:right;"></span>').appendTo(toolbar);
        var clearBtn = $('<button type="button" class="red-ui-button red-ui-button-small" title="' +
            RED._("sidebar.ai.clear", { defaultValue: "清空当前对话" }) + '"><i class="fa fa-trash-o"></i></button>')
            .appendTo(rightGroup);
        skillsBtn = $('<button type="button" class="red-ui-button red-ui-button-small" title="' +
            RED._("sidebar.ai.skills", { defaultValue: "技能" }) + '"><i class="fa fa-book"></i></button>')
            .appendTo(rightGroup);
        settingsBtn = $('<button type="button" class="red-ui-button red-ui-button-small" title="' +
            RED._("sidebar.ai.settings", { defaultValue: "AI 设置" }) + '"><i class="fa fa-cog"></i></button>')
            .appendTo(rightGroup);

        chatPanel = $('<div class="red-ui-sidebar-ai-chat-panel"></div>').appendTo(content);
        chatList = $('<div class="red-ui-sidebar-ai-messages"></div>').appendTo(chatPanel);

        var inputWrapper = $('<div class="red-ui-sidebar-ai-input"></div>').appendTo(chatPanel);
        selectionList = $('<div class="red-ui-sidebar-ai-selection"></div>').appendTo(inputWrapper);
        attachmentList = $('<div class="red-ui-sidebar-ai-attachments"></div>').appendTo(inputWrapper);
        var inputRow = $('<div class="red-ui-sidebar-ai-input-row"></div>').appendTo(inputWrapper);
        attachBtn = $('<button type="button" class="red-ui-button red-ui-button-small red-ui-sidebar-ai-attach" title="' +
            RED._("sidebar.ai.attach", { defaultValue: "添加附件" }) + '"><i class="fa fa-paperclip"></i></button>').appendTo(inputRow);
        attachInput = $('<input type="file" multiple style="display:none">').appendTo(content);
        inputBox = $('<textarea rows="2" placeholder="' +
            RED._("sidebar.ai.placeholder", { defaultValue: "向 AI 询问设备相关的问题…" }) +
            '"></textarea>').appendTo(inputRow);
        sendBtn = $('<button type="button" class="red-ui-button" data-i18n="sidebar.ai.send">发送</button>').appendTo(inputRow);

        settingsPanel = $('<div class="red-ui-sidebar-ai-settings"></div>').appendTo(content).hide();
        buildSettingsPanel(settingsPanel);

        skillsPanel = $('<div class="red-ui-sidebar-ai-skills-panel"></div>').appendTo(content).hide();
        buildSkillsPanel(skillsPanel);

        sendBtn.on("click", onSend);
        inputBox.on("keydown", function (e) {
            if ((e.ctrlKey || e.metaKey) && e.key === "Enter") {
                e.preventDefault();
                onSend();
            }
        });
        clearBtn.on("click", function () {
            if (sending) { return; }
            var sid = activeSessionId;
            sessions[sid] = { conversation: [], renderedHtml: null };
            conversation = sessions[sid].conversation;
            chatList.empty();
            renderWelcome();
        });
        settingsBtn.on("click", toggleSettings);
        skillsBtn.on("click", toggleSkills);
        attachBtn.on("click", function () { attachInput.trigger("click"); });
        attachInput.on("change", onAttachmentsSelected);

        RED.events.on("view:selection-changed", onCanvasSelectionChanged);
        onCanvasSelectionChanged(RED.view.selection ? RED.view.selection() : null);

        RED.events.on("workspace:change", function (event) {
            var nextId = (event && event.workspace) || activeFlowSessionId();
            if (nextId === activeSessionId) { return; }
            activateSession(nextId);
        });
        RED.events.on("flows:remove", function (ws) {
            var id = ws && ws.id;
            if (!id) { return; }
            delete sessions[id];
            if (activeSessionId === id) {
                activateSession(activeFlowSessionId());
            }
        });

        RED.sidebar.addTab({
            id: "ai",
            label: RED._("sidebar.ai.label", { defaultValue: "AI" }),
            name: RED._("sidebar.ai.name", { defaultValue: "AI 助手" }),
            iconClass: "fa fa-magic",
            content: content,
            action: "core:show-ai-tab",
            pinned: false,
            enableOnEdit: true
        });

        RED.actions.add("core:show-ai-tab", function () { RED.sidebar.show("ai"); });

        loadConfig().then(function () {
            activeSessionId = activeFlowSessionId();
            var s = getSession(activeSessionId);
            conversation = s.conversation;
            renderWelcome();
            refreshSessionIndicator();
        });
    }

    function buildSettingsPanel(root) {
        var form = $('<div class="form-row red-ui-sidebar-ai-settings-form"></div>').appendTo(root);

        $('<h3></h3>').text(RED._("sidebar.ai.settingsTitle", { defaultValue: "AI 服务设置" })).appendTo(form);

        var providerRow = $('<div class="red-ui-sidebar-ai-settings-row"></div>').appendTo(form);
        $('<label></label>').text(RED._("sidebar.ai.provider", { defaultValue: "服务商" })).appendTo(providerRow);
        providerSelect = $('<select><option value="openai">OpenAI 兼容</option><option value="anthropic">Anthropic Claude</option></select>').appendTo(providerRow);

        var modelRow = $('<div class="red-ui-sidebar-ai-settings-row"></div>').appendTo(form);
        $('<label></label>').text(RED._("sidebar.ai.model", { defaultValue: "模型" })).appendTo(modelRow);
        modelInput = $('<input type="text" placeholder="gpt-4o-mini / claude-sonnet-4-6 / deepseek-chat …">').appendTo(modelRow);

        var baseRow = $('<div class="red-ui-sidebar-ai-settings-row"></div>').appendTo(form);
        $('<label></label>').text(RED._("sidebar.ai.baseUrl", { defaultValue: "Base URL" })).appendTo(baseRow);
        baseUrlInput = $('<input type="text" placeholder="https://api.openai.com">').appendTo(baseRow);

        var keyRow = $('<div class="red-ui-sidebar-ai-settings-row"></div>').appendTo(form);
        $('<label></label>').text(RED._("sidebar.ai.apiKey", { defaultValue: "API Key" })).appendTo(keyRow);
        apiKeyInput = $('<input type="password" placeholder="sk-…">').appendTo(keyRow);

        var hint = $('<div class="red-ui-sidebar-ai-hint"></div>').appendTo(form);
        hint.text(RED._("sidebar.ai.keyHint", { defaultValue: "Key 仅保存在服务端，留空表示沿用已有值。" }));

        var actions = $('<div class="red-ui-sidebar-ai-settings-actions"></div>').appendTo(form);
        var clearCfgBtn = $('<button type="button" class="red-ui-button red-ui-sidebar-ai-clear-config"></button>')
            .html('<i class="fa fa-eraser"></i> ' + RED._("sidebar.ai.clearConfig", { defaultValue: "清空配置" }))
            .appendTo(actions);
        saveBtn = $('<button type="button" class="red-ui-button red-ui-button-primary"></button>')
            .text(RED._("sidebar.ai.save", { defaultValue: "保存" }))
            .appendTo(actions);
        var cancelBtn = $('<button type="button" class="red-ui-button"></button>')
            .text(RED._("sidebar.ai.cancel", { defaultValue: "返回" }))
            .appendTo(actions);

        saveBtn.on("click", onSaveSettings);
        cancelBtn.on("click", function () { showChat(); });
        clearCfgBtn.on("click", onClearConfig);
    }

    function toggleSettings() {
        if (settingsPanel.is(":visible")) {
            showChat();
        } else {
            showSettings();
        }
    }

    function toggleSkills() {
        if (skillsPanel.is(":visible")) {
            showChat();
        } else {
            showSkills();
        }
    }

    function showSettings() {
        chatPanel.hide();
        skillsPanel.hide();
        applyConfigToForm();
        settingsPanel.show();
    }

    function showSkills() {
        chatPanel.hide();
        settingsPanel.hide();
        skillsPanel.show();
        refreshSkillsList();
    }

    function showChat() {
        settingsPanel.hide();
        skillsPanel.hide();
        chatPanel.show();
    }

    function refreshSkillsListIfOpen() {
        if (skillsPanel && skillsPanel.is(":visible")) { refreshSkillsList(); }
    }

    function buildSkillsPanel(root) {
        var header = $('<div class="red-ui-sidebar-ai-skills-header"></div>').appendTo(root);
        $('<h3></h3>').text(RED._("sidebar.ai.skillsTitle", { defaultValue: "技能管理" })).appendTo(header);
        var backBtn = $('<button type="button" class="red-ui-button red-ui-button-small"></button>')
            .html('<i class="fa fa-arrow-left"></i> ' + RED._("sidebar.ai.cancel", { defaultValue: "返回" }))
            .appendTo(header);
        backBtn.on("click", function () { showChat(); });

        var hint = $('<div class="red-ui-sidebar-ai-hint"></div>').appendTo(root);
        hint.html(RED._("sidebar.ai.skillsHint", { defaultValue: "技能是带 YAML 头部的 Markdown 指令文档。启用后会注入到 Agent 的系统提示中。" }) +
            '<br><span class="red-ui-sidebar-ai-skills-hint-mono">支持：URL · <code>npx skills add &lt;name&gt;</code> · 内置技能名（如 superpower）</span>');

        var urlRow = $('<div class="red-ui-sidebar-ai-skills-row"></div>').appendTo(root);
        $('<label></label>').text(RED._("sidebar.ai.skillUrl", { defaultValue: "安装技能" })).appendTo(urlRow);
        var urlInput = $('<input type="text" placeholder="https://… 或 npx skills add <name>">').appendTo(urlRow);
        var urlBtn = $('<button type="button" class="red-ui-button red-ui-button-small"></button>')
            .text(RED._("sidebar.ai.skillFetch", { defaultValue: "安装" }))
            .appendTo(urlRow);
        urlBtn.on("click", function () {
            var u = urlInput.val().trim();
            if (!u) { return; }
            urlBtn.prop("disabled", true);
            $.ajax({
                url: "ai/skills",
                method: "POST",
                contentType: "application/json",
                data: JSON.stringify({ spec: u })
            }).done(function () {
                urlInput.val("");
                refreshSkillsList();
                RED.notify(RED._("sidebar.ai.skillInstalled", { defaultValue: "技能已安装" }), "success");
            }).fail(function (xhr) {
                RED.notify((xhr.responseJSON && xhr.responseJSON.error) || xhr.statusText, "error");
            }).always(function () { urlBtn.prop("disabled", false); });
        });

        var fileRow = $('<div class="red-ui-sidebar-ai-skills-row"></div>').appendTo(root);
        $('<label></label>').text(RED._("sidebar.ai.skillUpload", { defaultValue: "上传本地文件" })).appendTo(fileRow);
        var skillFile = $('<input type="file" accept=".md,.markdown,text/markdown,text/plain">').appendTo(fileRow);
        skillFile.on("change", function (e) {
            var file = e.target.files && e.target.files[0];
            if (!file) { return; }
            if (file.size > 512 * 1024) {
                RED.notify(RED._("sidebar.ai.skillTooLarge", { defaultValue: "文件过大（最大 512KB）" }), "warning");
                skillFile.val("");
                return;
            }
            var reader = new FileReader();
            reader.onload = function () {
                $.ajax({
                    url: "ai/skills",
                    method: "POST",
                    contentType: "application/json",
                    data: JSON.stringify({ name: file.name.replace(/\.md$/i, ""), content: String(reader.result || "") })
                }).done(function () {
                    refreshSkillsList();
                    RED.notify(RED._("sidebar.ai.skillInstalled", { defaultValue: "技能已安装" }), "success");
                }).fail(function (xhr) {
                    RED.notify((xhr.responseJSON && xhr.responseJSON.error) || xhr.statusText, "error");
                });
            };
            reader.readAsText(file);
            skillFile.val("");
        });

        skillsListEl = $('<div class="red-ui-sidebar-ai-skills-list"></div>').appendTo(root);
    }

    function refreshSkillsList() {
        if (!skillsListEl) { return; }
        skillsListEl.empty();
        $.ajax({ url: "ai/skills", method: "GET" }).done(function (data) {
            var skills = (data && data.skills) || [];
            if (!skills.length) {
                $('<div class="red-ui-sidebar-ai-skills-empty"></div>')
                    .text(RED._("sidebar.ai.skillEmpty", { defaultValue: "尚未安装任何技能。" }))
                    .appendTo(skillsListEl);
                return;
            }
            skills.forEach(function (s) {
                var row = $('<div class="red-ui-sidebar-ai-skill"></div>').appendTo(skillsListEl);
                var head = $('<div class="red-ui-sidebar-ai-skill-head"></div>').appendTo(row);
                var enableLabel = $('<label class="red-ui-sidebar-ai-skill-toggle"></label>').appendTo(head);
                var cb = $('<input type="checkbox">').appendTo(enableLabel);
                cb.prop("checked", s.enabled !== false);
                $('<span></span>').text(s.name).appendTo(enableLabel);
                cb.on("change", function () {
                    $.ajax({
                        url: "ai/skills/" + encodeURIComponent(s.id),
                        method: "PUT",
                        contentType: "application/json",
                        data: JSON.stringify({ enabled: cb.is(":checked") })
                    }).fail(function (xhr) {
                        RED.notify((xhr.responseJSON && xhr.responseJSON.error) || xhr.statusText, "error");
                        cb.prop("checked", !cb.is(":checked"));
                    });
                });
                var del = $('<button type="button" class="red-ui-button red-ui-button-small red-ui-sidebar-ai-skill-delete" title="' +
                    RED._("sidebar.ai.skillDelete", { defaultValue: "删除技能" }) + '"><i class="fa fa-trash-o"></i></button>')
                    .appendTo(head);
                del.on("click", function () {
                    $.ajax({ url: "ai/skills/" + encodeURIComponent(s.id), method: "DELETE" })
                        .done(function () { refreshSkillsList(); })
                        .fail(function (xhr) { RED.notify((xhr.responseJSON && xhr.responseJSON.error) || xhr.statusText, "error"); });
                });
                if (s.description) {
                    $('<div class="red-ui-sidebar-ai-skill-desc"></div>').text(s.description).appendTo(row);
                }
                if (s.sourceUrl) {
                    $('<div class="red-ui-sidebar-ai-skill-source"></div>').text(s.sourceUrl).appendTo(row);
                }
            });
        }).fail(function (xhr) {
            $('<div class="red-ui-sidebar-ai-error"></div>')
                .text((xhr.responseJSON && xhr.responseJSON.error) || xhr.statusText)
                .appendTo(skillsListEl);
        });
    }

    function applyConfigToForm() {
        var c = configCache || {};
        providerSelect.val(c.provider || "openai");
        modelInput.val(c.model || "");
        baseUrlInput.val(c.baseUrl || "");
        apiKeyInput.val("").attr("placeholder", c.hasApiKey ? (c.apiKeyHint || "（已保存）") : "sk-…");
    }

    function onSaveSettings() {
        var body = {
            provider: providerSelect.val(),
            baseUrl: baseUrlInput.val().trim(),
            model: modelInput.val().trim()
        };
        var keyVal = apiKeyInput.val();
        if (keyVal !== "") {
            body.apiKey = keyVal;
        }
        saveBtn.prop("disabled", true);
        $.ajax({
            url: "ai/config",
            method: "POST",
            contentType: "application/json",
            data: JSON.stringify(body)
        }).done(function (cfg) {
            configCache = cfg;
            RED.notify(RED._("sidebar.ai.savedNotice", { defaultValue: "AI 设置已保存" }), "success");
            showChat();
        }).fail(function (xhr) {
            RED.notify("保存失败：" + (xhr.responseJSON && xhr.responseJSON.error || xhr.statusText), "error");
        }).always(function () {
            saveBtn.prop("disabled", false);
        });
    }

    function onClearConfig() {
        var notification = RED.notify(
            RED._("sidebar.ai.clearConfigConfirm", {
                defaultValue: "确认清空 AI 配置？API Key、服务商、Base URL 等都会从服务器删除，操作不可撤销。"
            }),
            {
                type: "warning",
                fixed: true,
                modal: true,
                buttons: [
                    {
                        text: RED._("common.label.cancel", { defaultValue: "取消" }),
                        click: function () { notification.close(); }
                    },
                    {
                        text: RED._("sidebar.ai.clearConfig", { defaultValue: "清空配置" }),
                        class: "primary",
                        click: function () {
                            notification.close();
                            $.ajax({ url: "ai/config", method: "DELETE" })
                                .done(function (cfg) {
                                    configCache = cfg || { provider: "openai", hasApiKey: false };
                                    applyConfigToForm();
                                    RED.notify(RED._("sidebar.ai.clearConfigDone", {
                                        defaultValue: "AI 配置已清空"
                                    }), "success");
                                })
                                .fail(function (xhr) {
                                    RED.notify(
                                        (xhr.responseJSON && xhr.responseJSON.error) || xhr.statusText || "清空失败",
                                        "error"
                                    );
                                });
                        }
                    }
                ]
            }
        );
    }

    function loadConfig() {
        return $.ajax({ url: "ai/config", method: "GET" }).then(function (cfg) {
            configCache = cfg;
            return cfg;
        }).catch(function () {
            configCache = { provider: "openai", hasApiKey: false };
            return configCache;
        });
    }

    function ensureConfigured() {
        if (configCache && configCache.hasApiKey) { return true; }
        RED.notify(RED._("sidebar.ai.needConfig", { defaultValue: "请先在 AI 设置中配置 API Key。" }), "warning");
        showSettings();
        return false;
    }

    function renderWelcome() {
        if (chatList.children().length > 0) { return; }
        var wrap = $('<div class="red-ui-sidebar-ai-msg red-ui-sidebar-ai-msg-system"></div>').appendTo(chatList);
        $('<div class="red-ui-sidebar-ai-msg-body"></div>').html(
            '<p>' + escapeHtml(RED._("sidebar.ai.welcome", {
                defaultValue: "你好 — 我可以帮你在 Node-RED 中接入 IoT 设备。可通过附件按钮上传协议文档，或直接提问。"
            })) + '</p>' +
            (configCache && configCache.hasApiKey ? '' :
                '<p><em>' + escapeHtml(RED._("sidebar.ai.welcomeConfig", {
                    defaultValue: "首次使用？请先点击右上角齿轮图标配置服务商和 API Key。"
                })) + '</em></p>')
        ).appendTo(wrap);
    }

    function scrollChatToBottom() {
        if (!chatList || !chatList.length) { return; }
        var el = chatList[0];
        requestAnimationFrame(function () { el.scrollTop = el.scrollHeight; });
    }

    function appendMessage(role, text, opts) {
        var cls = "red-ui-sidebar-ai-msg red-ui-sidebar-ai-msg-" + role;
        var wrap = $('<div></div>', { class: cls }).appendTo(chatList);
        var body = $('<div class="red-ui-sidebar-ai-msg-body"></div>').appendTo(wrap);
        if (opts && opts.html) {
            body.html(text);
        } else {
            body.html(renderMarkdown(text));
        }
        scrollChatToBottom();
        return body;
    }

    function renderMarkdown(text) {
        if (!text) { return ""; }
        if (RED.utils && typeof RED.utils.renderMarkdown === "function") {
            return RED.utils.renderMarkdown(text);
        }
        return "<pre>" + escapeHtml(text) + "</pre>";
    }

    function escapeHtml(s) {
        return String(s).replace(/[&<>"']/g, function (ch) {
            return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch];
        });
    }

    function buildTypingIndicator() {
        return '<span class="red-ui-sidebar-ai-typing" aria-label="thinking">' +
            '<span class="red-ui-sidebar-ai-typing-dot"></span>' +
            '<span class="red-ui-sidebar-ai-typing-dot"></span>' +
            '<span class="red-ui-sidebar-ai-typing-dot"></span>' +
            '</span>';
    }

    function onSend() {
        if (sending) { return; }
        if (!ensureConfigured()) { return; }
        var text = inputBox.val().trim();
        if (!text && !pendingAttachments.length) { return; }
        if (!text) { text = RED._("sidebar.ai.attachOnlyPrompt", { defaultValue: "请帮我看一下附件内容。" }); }
        inputBox.val("");
        var attachmentChips = pendingAttachments.map(function (a) { return a.name; });
        var displayText = text;
        if (attachmentChips.length) {
            displayText += "\n\n_" +
                RED._("sidebar.ai.uploadedFile", { defaultValue: "已上传协议" }) +
                ": " + attachmentChips.join(", ") + "_";
        }
        appendMessage("user", displayText);
        var selectionContext = buildSelectionContextMessage();
        var modelText = text + consumePendingAttachments();
        if (selectionContext) {
            modelText = "[Canvas selection context]\n" + selectionContext + "\n\n[User request]\n" + modelText;
        }
        conversation.push({ role: "user", content: modelText });
        sendChat();
    }

    function sendChat() {
        sending = true;
        var pending = appendMessage("assistant", buildTypingIndicator(), { html: true });
        runAgentLoop(pending);
    }

    function runAgentLoop(pending) {
        var iterations = 0;
        var MAX_ITERATIONS = 8;

        function step() {
            iterations++;
            if (iterations > MAX_ITERATIONS) {
                pending.html('<span class="red-ui-sidebar-ai-error">' +
                    escapeHtml(RED._("sidebar.ai.tooManySteps", { defaultValue: "已中止：Agent 步骤过多" })) + '</span>');
                sending = false;
                return;
            }
            $.ajax({
                url: "ai/agent",
                method: "POST",
                contentType: "application/json",
                data: JSON.stringify({ messages: conversation })
            }).done(function (data) {
                var content = data.content || "";
                var toolCalls = data.toolCalls || [];
                if (content) {
                    if (pending) { pending.html(renderMarkdown(content)); pending = null; }
                    else { appendMessage("assistant", content); }
                    scrollChatToBottom();
                }
                if (!toolCalls.length) {
                    conversation.push({ role: "assistant", content: content });
                    if (pending) {
                        if (content) { pending.html(renderMarkdown(content)); }
                        else { pending.closest(".red-ui-sidebar-ai-msg").remove(); }
                    }
                    sending = false;
                    scrollChatToBottom();
                    return;
                }
                conversation.push({ role: "assistant", content: content, toolCalls: toolCalls });
                if (pending && !content) { pending.closest(".red-ui-sidebar-ai-msg").remove(); pending = null; }
                executeToolCalls(toolCalls).then(function (results) {
                    results.forEach(function (r) {
                        conversation.push({ role: "tool", toolCallId: r.id, content: JSON.stringify(r.result) });
                    });
                    pending = appendMessage("assistant", buildTypingIndicator(), { html: true });
                    scrollChatToBottom();
                    step();
                }).catch(function (err) {
                    var $msg = appendMessage("assistant", "", { html: true });
                    $msg.html('<span class="red-ui-sidebar-ai-error">' + escapeHtml(err.message || String(err)) + '</span>');
                    sending = false;
                    scrollChatToBottom();
                });
            }).fail(function (xhr) {
                var msg = (xhr.responseJSON && xhr.responseJSON.error) || xhr.statusText || "request failed";
                if (pending) { pending.html('<span class="red-ui-sidebar-ai-error">' + escapeHtml(msg) + '</span>'); }
                sending = false;
                scrollChatToBottom();
            });
        }

        step();
    }

    function executeToolCalls(toolCalls) {
        var promises = toolCalls.map(function (tc) {
            var card = appendToolCallCard(tc);
            return runOneTool(tc, card).then(function (result) {
                return { id: tc.id, result: result };
            }, function (err) {
                return { id: tc.id, result: { error: err.message || String(err) } };
            });
        });
        return Promise.all(promises);
    }

    function appendToolCallCard(tc) {
        var $msg = $('<div class="red-ui-sidebar-ai-msg red-ui-sidebar-ai-msg-tool"></div>').appendTo(chatList);
        var $body = $('<div class="red-ui-sidebar-ai-msg-body"></div>').appendTo($msg);
        var $card = $('<div class="red-ui-sidebar-ai-toolcall"></div>').appendTo($body);
        $('<i class="fa fa-cog red-ui-sidebar-ai-toolcall-icon"></i>').appendTo($card);
        $('<span class="red-ui-sidebar-ai-toolcall-name"></span>').text(tc.name).appendTo($card);
        var hint = describeToolCall(tc);
        if (hint) { $('<span class="red-ui-sidebar-ai-toolcall-hint"></span>').text(" — " + hint).appendTo($card); }
        $('<span class="red-ui-sidebar-ai-toolcall-status"></span>').appendTo($card);
        scrollChatToBottom();
        return $card;
    }

    function describeToolCall(tc) {
        var a = tc.arguments || {};
        if (tc.name === "add_subflow") { return (a.subflow && a.subflow.name) || (a.explanation || "").slice(0, 60); }
        if (tc.name === "add_nodes") { return ((a.nodes && a.nodes.length) || 0) + " nodes — " + ((a.explanation || "").slice(0, 60)); }
        if (tc.name === "update_node" || tc.name === "delete_node" || tc.name === "get_node_config") { return a.nodeId; }
        if (tc.name === "wire_nodes") { return ((a.edits && a.edits.length) || 0) + " edits — " + ((a.explanation || "").slice(0, 60)); }
        if (tc.name === "search_palette") { return JSON.stringify(a.query || ""); }
        if (tc.name === "install_palette_module") { return a.module + (a.version ? "@" + a.version : ""); }
        if (tc.name === "get_node_info") { return a.nodeType; }
        return "";
    }

    function setToolStatus(card, label, cls) {
        var $s = card.find(".red-ui-sidebar-ai-toolcall-status");
        $s.text(" • " + label);
        card.removeClass("red-ui-sidebar-ai-toolcall-pending red-ui-sidebar-ai-toolcall-done red-ui-sidebar-ai-toolcall-rejected red-ui-sidebar-ai-toolcall-error")
            .addClass("red-ui-sidebar-ai-toolcall-" + cls);
    }

    function runOneTool(tc, card) {
        var name = tc.name;
        var args = tc.arguments || {};
        var WRITE_TOOLS = {
            add_subflow: 1, add_nodes: 1, update_node: 1, wire_nodes: 1,
            delete_node: 1, install_palette_module: 1, install_skill_from_url: 1
        };
        var isWrite = !!WRITE_TOOLS[name];
        var execute = function () {
            try {
                if (name === "list_installed_node_types") {
                    var types = (RED.nodes.registry.getNodeTypes() || [])
                        .filter(function (t) { return t && t.indexOf("subflow") !== 0; });
                    return Promise.resolve({ ok: true, types: types });
                }
                if (name === "get_node_info") {
                    return Promise.resolve(getNodeInfo(args.nodeType));
                }
                if (name === "list_flows") {
                    var flows = [];
                    var activeId = RED.workspaces.active();
                    RED.nodes.eachWorkspace(function (ws) {
                        flows.push({ id: ws.id, label: ws.label || "", disabled: !!ws.disabled, active: ws.id === activeId });
                    });
                    return Promise.resolve({ ok: true, activeFlowId: activeId, flows: flows });
                }
                if (name === "get_current_flow") {
                    var ws = RED.workspaces.active();
                    var nodes = [];
                    RED.nodes.eachNode(function (n) { if (n.z === ws) { nodes.push(serializeNode(n)); } });
                    return Promise.resolve({ ok: true, flowId: ws, nodes: nodes });
                }
                if (name === "get_selection") {
                    var sel = RED.view.selection() || {};
                    var selNodes = (sel.nodes || []).map(serializeNode);
                    var selFlows = (sel.flows || []).map(function (f) { return { id: f.id, label: f.label }; });
                    return Promise.resolve({ ok: true, nodes: selNodes, flows: selFlows, count: selNodes.length });
                }
                if (name === "get_node_config") {
                    var node = RED.nodes.node(args.nodeId);
                    if (!node) { return Promise.resolve({ ok: false, error: "node not found: " + args.nodeId }); }
                    return Promise.resolve({ ok: true, node: serializeNode(node) });
                }
                if (name === "search_palette") {
                    return searchPalette(args.query || "");
                }
                if (name === "install_palette_module") {
                    return installPaletteModule(args.module, args.version);
                }
                if (name === "add_subflow") {
                    return Promise.resolve(applyAddSubflow(args));
                }
                if (name === "add_nodes") {
                    return Promise.resolve(applyAddNodes(args));
                }
                if (name === "update_node") {
                    return Promise.resolve(applyUpdateNode(args));
                }
                if (name === "wire_nodes") {
                    return Promise.resolve(applyWireNodes(args));
                }
                if (name === "delete_node") {
                    return Promise.resolve(applyDeleteNode(args));
                }
                if (name === "tap_nodes") {
                    if (!Array.isArray(args.nodeIds) || !args.nodeIds.length) {
                        return Promise.resolve({ ok: false, error: "nodeIds required" });
                    }
                    return $.ajax({
                        url: "ai/tap",
                        method: "POST",
                        contentType: "application/json",
                        data: JSON.stringify({
                            nodeIds: args.nodeIds,
                            durationMs: args.durationMs,
                            maxMessages: args.maxMessages
                        })
                    }).catch(function (xhr) {
                        return { ok: false, error: (xhr.responseJSON && xhr.responseJSON.error) || xhr.statusText };
                    });
                }
                if (name === "list_skills") {
                    return $.ajax({ url: "ai/skills", method: "GET" })
                        .then(function (data) {
                            var rows = (data.skills || []).map(function (s) {
                                return { id: s.id, name: s.name, description: s.description, enabled: s.enabled !== false };
                            });
                            return { ok: true, skills: rows };
                        });
                }
                if (name === "read_skill") {
                    if (!args.skillId) { return Promise.resolve({ ok: false, error: "skillId required" }); }
                    return $.ajax({ url: "ai/skills/" + encodeURIComponent(args.skillId), method: "GET" })
                        .then(function (data) {
                            return { ok: true, id: data.id, name: data.name, description: data.description, body: data.body };
                        }).catch(function (xhr) {
                            return { ok: false, error: (xhr.responseJSON && xhr.responseJSON.error) || xhr.statusText };
                        });
                }
                if (name === "install_skill_from_url") {
                    var spec = args.spec || args.url;
                    if (!spec) { return Promise.resolve({ ok: false, error: "spec required" }); }
                    return $.ajax({
                        url: "ai/skills",
                        method: "POST",
                        contentType: "application/json",
                        data: JSON.stringify({ spec: spec })
                    }).then(function (record) {
                        if (typeof refreshSkillsListIfOpen === "function") { refreshSkillsListIfOpen(); }
                        return { ok: true, id: record.id, name: record.name, description: record.description };
                    }).catch(function (xhr) {
                        return { ok: false, error: (xhr.responseJSON && xhr.responseJSON.error) || xhr.statusText };
                    });
                }
                return Promise.resolve({ ok: false, error: "unknown tool: " + name });
            } catch (err) {
                return Promise.resolve({ ok: false, error: err.message || String(err) });
            }
        };
        if (!isWrite) {
            setToolStatus(card, RED._("sidebar.ai.toolRunning", { defaultValue: "执行中" }), "pending");
            return execute().then(function (r) {
                setToolStatus(card, r.ok === false ? RED._("sidebar.ai.toolFailed", { defaultValue: "失败" }) : RED._("sidebar.ai.toolDone", { defaultValue: "完成" }),
                    r.ok === false ? "error" : "done");
                return r;
            });
        }
        setToolStatus(card, RED._("sidebar.ai.toolWaiting", { defaultValue: "等待审批" }), "pending");
        return askApproval(tc, card).then(function (approved) {
            if (!approved) {
                setToolStatus(card, RED._("sidebar.ai.toolRejected", { defaultValue: "被用户拒绝" }), "rejected");
                return { ok: false, error: "user rejected the action" };
            }
            return execute().then(function (r) {
                setToolStatus(card, r.ok === false ? RED._("sidebar.ai.toolFailed", { defaultValue: "失败" }) : RED._("sidebar.ai.toolDone", { defaultValue: "完成" }),
                    r.ok === false ? "error" : "done");
                return r;
            });
        });
    }

    function askApproval(tc, card) {
        return new Promise(function (resolve) {
            var $approve = $('<div class="red-ui-sidebar-ai-approve"></div>').appendTo(card);
            $('<span></span>').text(RED._("sidebar.ai.approveQuestion", { defaultValue: "执行此操作？" })).appendTo($approve);
            var $yes = $('<button type="button" class="red-ui-button red-ui-button-small red-ui-button-primary"></button>')
                .text(RED._("sidebar.ai.approve", { defaultValue: "同意" })).appendTo($approve);
            var $no = $('<button type="button" class="red-ui-button red-ui-button-small"></button>')
                .text(RED._("sidebar.ai.reject", { defaultValue: "拒绝" })).appendTo($approve);
            $yes.on("click", function () { $approve.remove(); resolve(true); });
            $no.on("click", function () { $approve.remove(); resolve(false); });
        });
    }

    function serializeNode(n) {
        var copy = {};
        Object.keys(n).forEach(function (k) {
            if (k.startsWith("_") || k === "g" || k === "h" || k === "w" || k === "dirty" || k === "changed" || k === "moved") { return; }
            copy[k] = n[k];
        });
        return copy;
    }

    function applyAddSubflow(args) {
        if (!args.subflow || typeof args.subflow !== "object") { return { ok: false, error: "subflow object missing" }; }
        var payload = [args.subflow].concat(Array.isArray(args.nodes) ? args.nodes : []);
        var result = RED.view.importNodes(payload, {
            generateIds: true,
            addFlow: false,
            touchImport: true,
            notify: false
        });
        return { ok: true, importedSubflowId: args.subflow.id, addedNodeCount: (args.nodes || []).length, result: summariseImport(result) };
    }

    function applyAddNodes(args) {
        if (!Array.isArray(args.nodes) || !args.nodes.length) { return { ok: false, error: "nodes array empty" }; }
        var ws = RED.workspaces.active();
        var prepared = args.nodes.map(function (n) { var c = Object.assign({}, n); c.z = ws; return c; });
        var result = RED.view.importNodes(prepared, { generateIds: true, addFlow: false, touchImport: true, notify: false });
        return { ok: true, addedNodeCount: prepared.length, result: summariseImport(result) };
    }

    function applyUpdateNode(args) {
        var node = RED.nodes.node(args.nodeId);
        if (!node) { return { ok: false, error: "node not found: " + args.nodeId }; }
        var patch = args.patch || {};
        var oldValues = {};
        Object.keys(patch).forEach(function (k) {
            if (k === "id" || k === "type") { return; }
            oldValues[k] = node[k];
            node[k] = patch[k];
        });
        node.changed = true;
        node.dirty = true;
        RED.events.emit("nodes:change", node);
        RED.history.push({ t: "edit", node: node, changes: oldValues, dirty: RED.nodes.dirty() });
        RED.nodes.dirty(true);
        RED.view.redraw(true);
        return { ok: true, nodeId: args.nodeId, changedKeys: Object.keys(oldValues) };
    }

    function applyWireNodes(args) {
        var edits = Array.isArray(args.edits) ? args.edits : [];
        if (!edits.length) { return { ok: false, error: "edits array empty" }; }
        var changed = [];
        edits.forEach(function (e) {
            var src = RED.nodes.node(e.sourceId);
            if (!src) { return; }
            var port = typeof e.sourcePort === "number" ? e.sourcePort : 0;
            if (!Array.isArray(src.wires)) { src.wires = []; }
            while (src.wires.length <= port) { src.wires.push([]); }
            var arr = src.wires[port];
            var idx = arr.indexOf(e.targetId);
            if (e.op === "connect" && idx === -1) { arr.push(e.targetId); changed.push(e); }
            else if (e.op === "disconnect" && idx !== -1) { arr.splice(idx, 1); changed.push(e); }
            src.changed = true;
            src.dirty = true;
            RED.events.emit("nodes:change", src);
        });
        if (!changed.length) { return { ok: true, nodeId: null, applied: 0, message: "no edits applied (already in target state)" }; }
        RED.nodes.dirty(true);
        RED.view.redraw(true);
        return { ok: true, applied: changed.length };
    }

    function applyDeleteNode(args) {
        var node = RED.nodes.node(args.nodeId);
        if (!node) { return { ok: false, error: "node not found: " + args.nodeId }; }
        var removed = RED.nodes.remove(args.nodeId);
        RED.nodes.eachNode(function (n) {
            if (Array.isArray(n.wires)) {
                n.wires.forEach(function (arr, i) {
                    var idx = arr.indexOf(args.nodeId);
                    while (idx !== -1) { arr.splice(idx, 1); idx = arr.indexOf(args.nodeId); }
                });
            }
        });
        RED.nodes.dirty(true);
        RED.view.redraw(true);
        return { ok: true, removedNodeId: args.nodeId };
    }

    function getNodeInfo(nodeType) {
        if (!nodeType) { return { ok: false, error: "nodeType required" }; }
        var def = RED.nodes.getType(nodeType);
        if (!def) { return { ok: false, error: "unknown node type: " + nodeType }; }
        var defaults = {};
        Object.keys(def.defaults || {}).forEach(function (k) {
            var d = def.defaults[k];
            defaults[k] = {
                type: d && d.type ? (typeof d.type === "string" ? d.type : "config-node") : (typeof d.value),
                value: d && d.value,
                required: !!(d && d.required)
            };
        });
        var help = "";
        try {
            var $help = RED.nodes.getNodeHelp(nodeType);
            if ($help) { help = $.text($help).slice(0, 800); }
        } catch (e) {}
        return {
            ok: true,
            type: nodeType,
            category: def.category,
            inputs: def.inputs,
            outputs: def.outputs,
            defaults: defaults,
            help: help
        };
    }

    var paletteCatalogCache = null;

    function searchPalette(query) {
        var q = (query || "").toLowerCase().trim();
        if (!q) { return Promise.resolve({ ok: false, error: "query required" }); }
        var loadCatalogue = paletteCatalogCache
            ? Promise.resolve(paletteCatalogCache)
            : new Promise(function (resolve) {
                  var urls = (RED.settings.theme && RED.settings.theme("palette.catalogues"))
                      || ["https://catalogue.nodered.org/catalogue.json"];
                  var pending = urls.length;
                  var modules = [];
                  urls.forEach(function (u) {
                      $.getJSON(u).done(function (data) {
                          if (data && Array.isArray(data.modules)) { modules = modules.concat(data.modules); }
                      }).always(function () {
                          if (--pending === 0) {
                              paletteCatalogCache = modules;
                              resolve(modules);
                          }
                      });
                  });
              });
        return loadCatalogue.then(function (modules) {
            var matches = modules.filter(function (m) {
                return (m.id || "").toLowerCase().indexOf(q) !== -1
                    || (m.description || "").toLowerCase().indexOf(q) !== -1
                    || (Array.isArray(m.keywords) && m.keywords.some(function (k) { return (k || "").toLowerCase().indexOf(q) !== -1; }));
            }).slice(0, 10).map(function (m) {
                return {
                    module: m.id,
                    version: m.version,
                    description: (m.description || "").slice(0, 200),
                    keywords: m.keywords || [],
                    url: m.url
                };
            });
            return { ok: true, query: query, count: matches.length, results: matches };
        });
    }

    function installPaletteModule(moduleName, version) {
        if (!moduleName) { return Promise.resolve({ ok: false, error: "module name required" }); }
        return $.ajax({
            url: "nodes",
            method: "POST",
            contentType: "application/json",
            data: JSON.stringify(version ? { module: moduleName, version: version } : { module: moduleName })
        }).then(function (data) {
            return { ok: true, module: moduleName, version: data && data.version, addedTypes: data && data.types };
        }, function (xhr) {
            var msg = (xhr.responseJSON && xhr.responseJSON.message) || xhr.responseText || xhr.statusText;
            return { ok: false, error: "install failed: " + msg };
        });
    }

    function summariseImport(r) {
        if (!r) { return null; }
        return {
            nodes: (r.nodes || []).length,
            subflows: (r.subflows || []).length,
            workspaces: (r.workspaces || []).length
        };
    }

    function onAttachmentsSelected() {
        var files = attachInput[0].files;
        if (!files || !files.length) { return; }
        var queue = Array.prototype.slice.call(files);
        attachInput.val("");
        queue.forEach(function (file) { readAttachment(file); });
    }

    function readAttachment(file) {
        if (file.size > MAX_ATTACHMENT_BYTES) {
            RED.notify(RED._("sidebar.ai.attachTooLarge", { defaultValue: "文件过大（最大 200KB）" }) + ": " + file.name, "warning");
            return;
        }
        var reader = new FileReader();
        reader.onload = function () {
            var text = String(reader.result || "");
            if (!text || !text.trim()) {
                RED.notify(RED._("sidebar.ai.emptyDoc", { defaultValue: "文件内容为空" }) + ": " + file.name, "warning");
                return;
            }
            if (looksBinary(text)) {
                RED.notify(RED._("sidebar.ai.attachBinary", { defaultValue: "不支持二进制文件" }) + ": " + file.name, "warning");
                return;
            }
            pendingAttachments.push({ name: file.name, size: file.size, content: text });
            renderAttachments();
        };
        reader.onerror = function () {
            RED.notify("读取文件失败：" + file.name, "error");
        };
        reader.readAsText(file);
    }

    function looksBinary(text) {
        var sample = text.slice(0, 1000);
        var nonPrintable = 0;
        for (var i = 0; i < sample.length; i++) {
            var code = sample.charCodeAt(i);
            if (code === 0) { return true; }
            if (code < 9 || (code > 13 && code < 32)) { nonPrintable++; }
        }
        return nonPrintable / Math.max(1, sample.length) > 0.1;
    }

    function renderAttachments() {
        attachmentList.empty();
        pendingAttachments.forEach(function (att, idx) {
            var chip = $('<span class="red-ui-sidebar-ai-attachment-chip"></span>').appendTo(attachmentList);
            $('<i class="fa fa-file-text-o"></i>').appendTo(chip);
            $('<span></span>').text(" " + att.name + " (" + formatSize(att.size) + ")").appendTo(chip);
            $('<button type="button" class="red-ui-sidebar-ai-attachment-remove" title="' +
                RED._("sidebar.ai.removeAttach", { defaultValue: "移除" }) + '"><i class="fa fa-times"></i></button>')
                .appendTo(chip)
                .on("click", function () {
                    pendingAttachments.splice(idx, 1);
                    renderAttachments();
                });
        });
    }

    function onCanvasSelectionChanged(selection) {
        var ids = [];
        if (selection && Array.isArray(selection.nodes)) {
            selection.nodes.forEach(function (n) { if (n && n.id) { ids.push(n.id); } });
        }
        if (ids.length === 0) { dismissedNodeIds = {}; }
        contextNodeIds = ids.filter(function (id) { return !dismissedNodeIds[id]; });
        renderSelectionChips();
    }

    function renderSelectionChips() {
        if (!selectionList) { return; }
        selectionList.empty();
        if (!contextNodeIds.length) { return; }
        var label = $('<span class="red-ui-sidebar-ai-selection-label"></span>').appendTo(selectionList);
        label.html('<i class="fa fa-mouse-pointer"></i> ' +
            escapeHtml(RED._("sidebar.ai.selectionLabel", { defaultValue: "正在编辑" })) + ":");
        contextNodeIds.forEach(function (id, idx) {
            var node = RED.nodes.node(id);
            if (!node) { return; }
            var chip = $('<span class="red-ui-sidebar-ai-selection-chip"></span>').appendTo(selectionList);
            var labelText = (node.name || node.type) + " " + chipNodeBadge(node);
            $('<a href="#"></a>').text(labelText).appendTo(chip).on("click", function (e) {
                e.preventDefault();
                if (RED.view && RED.view.reveal) { RED.view.reveal(id); }
            });
            $('<button type="button" class="red-ui-sidebar-ai-selection-remove" title="' +
                escapeHtml(RED._("sidebar.ai.removeSelection", { defaultValue: "从上下文移除" })) +
                '"><i class="fa fa-times"></i></button>')
                .appendTo(chip)
                .on("click", function () {
                    dismissedNodeIds[id] = true;
                    contextNodeIds.splice(idx, 1);
                    renderSelectionChips();
                });
        });
    }

    function chipNodeBadge(node) {
        var t = node.type || "";
        var idShort = (node.id || "").slice(0, 6);
        return "[" + t + "·" + idShort + "]";
    }

    function buildSelectionContextMessage() {
        if (!contextNodeIds.length) { return null; }
        var rows = contextNodeIds.map(function (id) {
            var n = RED.nodes.node(id);
            if (!n) { return null; }
            return "  - id=" + id + ", type=" + n.type + ", name=" + JSON.stringify(n.name || "");
        }).filter(Boolean);
        if (!rows.length) { return null; }
        return [
            "The user has selected the following node(s) on the canvas — they want changes applied to these specifically:",
            rows.join("\n"),
            "Before changing them, call get_node_config to read each node's current configuration, then use update_node with a minimal patch."
        ].join("\n");
    }

    function formatSize(bytes) {
        if (bytes < 1024) { return bytes + " B"; }
        if (bytes < 1024 * 1024) { return Math.round(bytes / 102.4) / 10 + " KB"; }
        return Math.round(bytes / 1024 / 102.4) / 10 + " MB";
    }

    function consumePendingAttachments() {
        if (!pendingAttachments.length) { return ""; }
        var blocks = pendingAttachments.map(function (att) {
            return "Attachment `" + att.name + "` (" + att.size + " bytes):\n```\n" + att.content + "\n```";
        });
        pendingAttachments = [];
        renderAttachments();
        return "\n\n" + blocks.join("\n\n");
    }


    return {
        init: init,
        show: function () { RED.sidebar.show("ai"); }
    };
})();
